### ✅ Function: `paginateArray`

```php
function paginateArray($array, $perPage = 10, $page = 1) {
    $totalItems = count($array);
    $currentPage = $page;
    $perPage = $perPage;

    // Calculate the start and end indices
    $startIndex = ($currentPage - 1) * $perPage;
    $ endIndex = $startIndex + $perPage;

    // Ensure we don't go beyond the array bounds
    $endIndex = min($endIndex, $totalItems);

    // Get the current page's items
    $paginatedArray = array_slice($array, $startIndex, $perPage);

    // Pagination info
    $totalPages = ceil($totalItems / $perPage);
    $prevPage = $currentPage - 1;
    $nextPage = $currentPage + 1;

    // Generate the pagination links
    $paginationLinks = '';
    if ($prevPage > 1) {
        $paginationLinks .= '<a href="?page=' . $prevPage . '">Previous</a> ';
    }
    if ($currentPage < $totalPages) {
        $paginationLinks .= '<a href="?page=' . $nextPage . '">Next</a>';
    }

    return [
        'items' => $paginatedArray,
        'totalItems' => $totalItems,
        'totalPages' => $totalPages,
        'currentPage' => $currentPage,
        'paginationLinks' => $paginationLinks
    ];
}
